  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00920",
          "explanation": "After a new nasal-feeding tolerance concern surfaced, the doctor reprioritized to immediate feeding/aspiration risk monitoring.",
          "quote": "老人鼻饲后是否有腹胀加重"
        },
        {
          "event_id": "lite_evt_00920",
          "explanation": "The updated plan includes an immediate notification threshold rather than waiting for routine review.",
          "quote": "一旦发现，立即按铃叫护士处理"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by evolving nasal feeding intolerance and ongoing coma. The doctor explicitly shifted the family’s near-term priority from broader reports/medications to aspiration, vomiting, abdominal distension, oxygen drop, and immediate nurse notification, while preserving later medication/result follow-up.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_01412",
          "explanation": "The doctor verifies ambiguity between old information and the current-day imaging result rather than accepting family/group interpretation.",
          "quote": "不能当成今天下午复查片子的正式结果"
        },
        {
          "event_id": "lite_evt_01739",
          "explanation": "The doctor distinguishes a potentially falsely reassuring EEG statement from overall safety or recovery.",
          "quote": "脑电没提示一直抽，但不等于好了"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by ambiguous family-reported EEG and imaging statements. The doctor repeatedly corrected false reassurance, separated old versus new reports, and routed interpretation to formal reports and the treating teams while maintaining uncertainty.",
      "ho_id": "HO2",
